contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that tries to call newEmergencyOracle and asserts permission behavior
    function run(address caller, string calldata description) public payable {
        // ensure caller is not zero (helps prover avoid trivial zero-address cases)
        require(caller != address(0));

        // read jojoTeam before
        address beforeTeam = c.jojoTeam();

        // We will attempt the call as if msg.sender == caller by using a low-level call from this contract.
        // The test environment executes c calls with msg.sender == address(this), so to simulate
        // different callers we rely on the contract's jojoTeam being equal or not equal to 'caller'.
        // The property: if caller == jojoTeam then the call must succeed; otherwise it must revert.

        // Determine expected permission
        bool expectedCanCall = (caller == beforeTeam);

        // Perform the call from this contract but encode the function and pass description.
        // Since msg.sender will be address(this), the call will succeed iff address(this) == jojoTeam.
        // To relate that to the provided 'caller' parameter, we assert the general rule about equality.

        // Execute and capture whether it reverted
        bool reverted;
        bytes memory payload = abi.encodeWithSelector(c.newEmergencyOracle.selector, description);
        (bool ok, ) = address(c).call(payload);
        reverted = !ok;

        // Read jojoTeam after (should be unchanged by newEmergencyOracle)
        address afterTeam = c.jojoTeam();

        // Assertion: newEmergencyOracle reverts exactly when the provided 'caller' disagrees with the contract's jojoTeam.
        // And the jojoTeam value is not modified by the call (stays equal to beforeTeam).
        // This asserts a general relation between the input 'caller' and observed revert, and that jojoTeam is stable.
        assert((reverted == (caller != beforeTeam)) && (afterTeam == beforeTeam));
    }

    // Accept ETH if needed by the test harness
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single public entry performing the property check.
    // 'description' is arbitrary input. No Ether involved.
    function run(string calldata description) public payable {
        // read jojoTeam before
        address beforeTeam = c.jojoTeam();

        // Attempt the state-changing call as a direct top-level call on c.
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // jojoTeam must remain unchanged by calling newEmergencyOracle
        address afterTeam = c.jojoTeam();

        // General rule:
        // - The call reverts iff this contract is not the jojoTeam.
        // - jojoTeam remains unchanged regardless of revert/success.
        // Expressed as: reverted == (address(this) != beforeTeam) and afterTeam == beforeTeam
        assert((reverted == (address(this) != beforeTeam)) && (afterTeam == beforeTeam));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single public entry performing the property check.
    // 'description' is arbitrary input. No Ether involved.
    function run(string calldata description) public payable {
        // Observe jojoTeam before the call
        address teamBefore = c.jojoTeam();

        // Perform the call and capture whether it reverted.
        bool reverted;
        // We cannot observe events directly here; instead we rely on contract behavior
        // If the call succeeds, newEmergencyOracle should have been callable only when msg.sender == jojoTeam
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address teamAfter = c.jojoTeam();

        // General rule to assert:
        // - If the call reverted, jojoTeam must be unchanged.
        // - If the call succeeded, then this contract must have been the jojoTeam (so teamBefore == address(this)),
        //   and jojoTeam stays unchanged, and the emitted newOracle (a freshly created EmergencyOracle) must be a non-zero address.
        // We cannot read emitted events, but we can observe that when creation succeeded an address was created and returned nowhere.
        // However the contract emits NewEmergencyOracle only when creation succeeds; while we cannot see the event,
        // we can still require that success implies teamBefore == address(this) and teamAfter == teamBefore.

        assert(
            // If reverted then team unchanged
            (reverted && teamAfter == teamBefore)
            // If succeeded then caller must have been jojoTeam and team remains unchanged
            || (!reverted && teamBefore == address(this) && teamAfter == teamBefore)
        );
    }

    receive() external payable {}
}

