        address teamBefore = c.jojoTeam();

        // Attempt the potentially-reverting call and record whether it reverted
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe jojoTeam after the call
        address teamAfter = c.jojoTeam();

        // General property to hold for all inputs and states:
        // - jojoTeam must never change as a result of calling newEmergencyOracle
        // - if the call succeeded (didn't revert), then the caller must have been jojoTeam
        //   (i.e. teamBefore == address(this)) and teamAfter equals teamBefore
        // - if the call reverted, we at least require teamAfter equals teamBefore (no change)

